// ============================================================
// TRANSFORMAR COMPROBANTES → FORMATO REPORTE DE LIQUIDACIONES
// MEJORADO: Identificación de banco por número de cuenta
// ============================================================

// ── Helper: forzar a string limpio (evita 7.01505E+12) ──────
function toSafeString(val) {
  if (val === null || val === undefined || val === '' || val === 'null') return '';
  const str = String(val).trim();
  if (/[eE]/.test(str) && !isNaN(Number(str))) {
    return BigInt(Math.round(Number(str))).toString();
  }
  return str;
}

// ── Helper: formatear monto numérico con 2 decimales ────────
function formatearMonto(valor) {
  const num = parseFloat(valor);
  if (isNaN(num)) return 0.00;
  return parseFloat(num.toFixed(2));
}

// ── Helper: formatear código de banco (4 dígitos) ───────────
function formatearCodigoBanco(codigo) {
  if (!codigo && codigo !== 0) return '';
  const s = String(codigo).trim();
  if (s === '') return '';
  return s.padStart(4, '0');
}

// ── Helper: fecha YYYY-MM-DD → DD/MM/YYYY ───────────────────
function formatearFecha(fecha) {
  if (!fecha) return '';
  const str = String(fecha).trim();
  const matchISO = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (matchISO) return `${matchISO[3]}/${matchISO[2]}/${matchISO[1]}`;
  const matchDMY = str.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (matchDMY) return str;
  return str;
}

// ── Helper: extraer solo dígitos de una cuenta (quita X, x, *, guiones, espacios, texto) ──
function extraerDigitos(cuenta) {
  if (!cuenta) return '';
  return String(cuenta)
    .replace(/[^0-9]/g, ''); // solo dígitos
}

// ── Helper: verificar si dos cuentas coinciden ──────────────
// Estrategia: extraer dígitos visibles de ambas y ver si uno contiene al otro
function cuentasCoinciden(cuentaDetectada, cuentaReferencia) {
  const digitosDetectados = extraerDigitos(cuentaDetectada);
  const digitosReferencia = extraerDigitos(cuentaReferencia);

  if (!digitosDetectados || digitosDetectados.length < 4) return false;
  if (!digitosReferencia || digitosReferencia.length < 4) return false;

  // Caso 1: coincidencia exacta
  if (digitosDetectados === digitosReferencia) return true;

  // Caso 2: los dígitos detectados están contenidos en la referencia
  // (ej: "392" está al final de "7015046986392")
  if (digitosReferencia.includes(digitosDetectados)) return true;

  // Caso 3: la referencia está contenida en los detectados
  if (digitosDetectados.includes(digitosReferencia)) return true;

  // Caso 4: coincidencia parcial por fragmentos
  // Separa por bloques de dígitos contiguos (ej: "701" y "86392" de "701XXXX86392")
  const bloques = String(cuentaDetectada)
    .replace(/[^0-9]+/g, ' ')
    .trim()
    .split(' ')
    .filter(b => b.length >= 3); // solo bloques de 3+ dígitos

  if (bloques.length === 0) return false;

  // Todos los bloques deben estar presentes en la cuenta de referencia
  return bloques.every(bloque => digitosReferencia.includes(bloque));
}

// ── Resolver banco por número de cuenta ─────────────────────
function resolverBancoPorCuenta(cuentaDestino, cuentaOrigen, refMap) {
  const candidatos = [cuentaDestino, cuentaOrigen]
    .filter(c => c && c !== 'null' && c !== 'undefined' && c !== '');

  for (const cuenta of candidatos) {
    for (const [abrev, datos] of Object.entries(refMap)) {
      if (datos.nroCuenta && cuentasCoinciden(cuenta, datos.nroCuenta)) {
        return datos;
      }
    }
  }

  return { codigoBanco: '', codigoCuenta: '', nroCuenta: '' };
}

// ============================================================
// 1. Leer referencias de bancos (input de este nodo)
// ============================================================
const refItems = $input.all().map(i => i.json);

const refMap = {};
refItems.forEach(r => {
  // col_1 = abreviatura del banco (BISA, BCP, etc.)
  const abrev = (r['col_1'] || '').toString().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();

  if (abrev) {
    refMap[abrev] = {
      codigoBanco:  formatearCodigoBanco(r['BANCO']),
      codigoCuenta: toSafeString(r['CUENTA']),
      nroCuenta:    toSafeString(r['NRO_CUENTA']) // ← nueva columna
    };
  }
});

// ============================================================
// 2. Comprobantes del día
// ============================================================
let _rows; try { _rows = $('Filtrar fecha COMP').all(); } catch(e) { try { _rows = $('Leer comprobantes (reporte)').all(); } catch(e2) { _rows = $('Leer comprobantes del día').all(); } }
const comprobantes = _rows.map(i => i.json);

// ============================================================
// 3. Agrupar por guía
// ============================================================
const porGuia = {};
comprobantes.forEach(c => {
  const guia = (c.guia || '').toString().trim();
  if (!guia) return;
  if (!porGuia[guia]) {
    porGuia[guia] = { totalMonto: 0, comprobantes: [] };
  }
  porGuia[guia].totalMonto += Number(c.monto) || 0;
  porGuia[guia].comprobantes.push(c);
});

// ============================================================
// 4. Construir filas
// ============================================================
const filas = [];

Object.entries(porGuia).forEach(([guia, data]) => {
  const matchGuia     = guia.toUpperCase().match(/([A-Z]+)-0*(\d+)/);
  const numeroGuia    = matchGuia ? matchGuia[2] : guia;
  const numeroGuiaInt = matchGuia ? parseInt(matchGuia[2], 10) : 0;
  const totalGuia     = formatearMonto(data.totalMonto);

  data.comprobantes.forEach(c => {

    // Resolver banco por número de cuenta (nueva lógica principal)
    const ref = resolverBancoPorCuenta(
      c.cuenta_destino,
      c.cuenta_origen,
      refMap
    );

    let fecha = c.fecha || '';
    if (String(fecha).length > 10) fecha = String(fecha).substring(0, 10);

    const redondeo = formatearMonto(c.redondeo ?? 0);

    filas.push({
      _numeroGuiaInt: numeroGuiaInt,
      json: {
        Transaccion:         'LCT',
        Serie:               matchGuia ? matchGuia[1] : 'COM',
        Guia:                numeroGuia,
        Documento:           '',
        Importe:             totalGuia,
        Percepcion:          0.00,
        Redondeo:            redondeo,
        Faltante:            0.00,
        Robo:                0.00,
        Total:               totalGuia,
        'Tipo Pago':         'BDB',
        Banco:               ref.codigoBanco,   // vacío si no encontró
        Cuenta:              ref.codigoCuenta,  // vacío si no encontró
        Fecha:               formatearFecha(fecha),
        Comprobante:         toSafeString(c.referencia || c.Comprobante || ''),
        Deposito:            formatearMonto(c.monto),
        phone:               toSafeString(c.phone || ''),
        advertencias:        c.advertencias || '',
        validacion:          c.validacion || '',
        hora:                c.hora || '',
        banco_billetera:     c.banco_billetera || '',
        banco_origen:        c.banco_origen || '',
        cuenta_destino:      toSafeString(c.cuenta_destino || ''),
        cuenta_origen:       toSafeString(c.cuenta_origen || ''),
        nombre_depositante:  c.nombre_depositante || '',
        nombre_beneficiario: c.nombre_beneficiario || '',
        agencia:             c.agencia || '',
        fecha_registro:      c.fecha_registro || '',
        link_img:            c.link_img || ''
      }
    });
  });
});

// ============================================================
// 5. Caso vacío
// ============================================================
if (filas.length === 0) {
  return [{
    json: {
      _sin_datos: true,
      resumen: 'No hay comprobantes confirmados para procesar.'
    }
  }];
}

// ============================================================
// 6. Ordenar por número de guía (menor a mayor)
// ============================================================
filas.sort((a, b) => a._numeroGuiaInt - b._numeroGuiaInt);

return filas.map(f => ({ json: f.json }));

