parameters.jsCode:
// ============================================================
// PREPARAR RESUMEN WA - DETECCIÓN POR BUTTON ID
// ============================================================

const email = $('Buscar autorizado').first().json.email || 'el correo registrado';

// ── Detectar qué tipo de reporte se solicitó ────────────────
const buttonId = $('Mapeamos datos del mensaje').first().json.buttonId || '';
// Detección robusta del tipo (cubre botones viejos, nuevos REP_/RNG_ y rango escrito por contexto)
let _ctx = '';
try { _ctx = String($('Resolver Sucursal').first().json.rep_pendiente || ''); } catch(e) {}
const esSesiones =
  buttonId === 'INFORME_SESIONES' ||
  /^REP_SES_/.test(buttonId) ||
  /^RNG_SES_/.test(buttonId) ||
  /^PENDIENTE_RANGO\|SES\|/.test(_ctx);

// ── Obtener datos según la rama ─────────────────────────────
let resumen = {};

if (esSesiones) {
  // ── REPORTE DE SESIONES ──────────────────────────────────
  let itemsSesiones = [];
  try {
    itemsSesiones = $('Transformar para reporte1')
      .all()
      .map(i => i.json)
      .filter(i => !i._sin_datos && i.Estado !== undefined);
  } catch (e) {
    itemsSesiones = [];
  }

  if (itemsSesiones.length === 0) {
    resumen = {
      tipo: 'VACIO',
      email,
      mensaje_wa: '⚠️ No se encontraron sesiones para generar el reporte.'
    };
  } else {
    const sesionesActivas = itemsSesiones.filter(
      i => String(i.Estado || '').toUpperCase() === 'ACTIVO'
    ).length;

    const sesionesCompletadas = itemsSesiones.filter(
      i => String(i.Estado || '').toUpperCase() === 'COMPLETADO'
    ).length;

    resumen = {
      tipo: 'SESIONES',
      total_sesiones: itemsSesiones.length,
      activas: sesionesActivas,
      completadas: sesionesCompletadas,
      email,
      mensaje_wa:
        `🚚 *Reporte de Sesiones*\n\n` +
        `📈 Total de sesiones: ${itemsSesiones.length}\n` +
        `🟢 Activas: ${sesionesActivas}\n` +
        `✅ Completadas: ${sesionesCompletadas}\n\n` +
        `📧 El detalle completo se envió a: ${email}`
    };
  }

} else {
  // ── REPORTE DE COMPROBANTES / LIQUIDACIONES ──────────────
  let itemsComprobantes = [];
  try {
    itemsComprobantes = $('Transformar para reporte')
      .all()
      .map(i => i.json)
      .filter(i => !i._sin_datos && i.Deposito !== undefined);
  } catch (e) {
    itemsComprobantes = [];
  }

  if (itemsComprobantes.length === 0) {
    resumen = {
      tipo: 'VACIO',
      email,
      mensaje_wa: '⚠️ No se encontraron comprobantes para generar el reporte.'
    };
  } else {
    const guiasUnicas = new Set(
      itemsComprobantes.map(i => i.Guia).filter(Boolean)
    );

    const totalDepositos = itemsComprobantes.reduce(
      (sum, i) => sum + (Number(i.Deposito) || 0),
      0
    );

    const totalFmt = totalDepositos.toLocaleString('es-BO', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });

    resumen = {
      tipo: 'COMPROBANTES',
      guias: guiasUnicas.size,
      comprobantes: itemsComprobantes.length,
      total_fmt: totalFmt,
      email,
      mensaje_wa:
        `📊 *Reporte de Liquidaciones*\n\n` +
        `✅ Guías: ${guiasUnicas.size}\n` +
        `✅ Comprobantes: ${itemsComprobantes.length}\n` +
        `💰 Total: Bs. ${totalFmt}\n\n` +
        `📧 El detalle completo se envió a: ${email}`
    };
  }
}

return [{ json: resumen }];

// ============================================================
// INFORME OPTIMIZADO: Sesiones + Liquidaciones
// ============================================================
const LINK_SHEET_LIQ = `https://docs.google.com/spreadsheets/d/${$vars.SHEET_ID_MAESTRO}/edit?usp=sharing`;

// --- Fuente 1: Sesiones ---
let _ses; try { _ses = $('Leer sesiones (informe)').all(); } catch(e) { _ses = $('Leer sesiones').all(); }
const todasSesiones = _ses.map(i => i.json);

// --- Fecha del día desde el maestro (columna FE, primera fila con dato) ---
let _liqAll; try { _liqAll = $('Leer Liquidaciones (informe)').all(); } catch(e) { _liqAll = $('Leer Liquidaciones').all(); }
const _filasMaestro = _liqAll.map(i => i.json);
let feDia = '';
for (const f of _filasMaestro) {
  if (f.FE && String(f.FE).trim()) { feDia = String(f.FE).trim(); break; }
}
// Convertir FE (dd/mm/aaaa) -> aaaa-mm-dd para comparar con s_fecha
function feAISO(d){ const m=String(d).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); 
  return m ? `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}` : ''; }
const fechaDiaISO = feAISO(feDia);

// --- Solo sesiones del DÍA (s_fecha == fecha del maestro) ---
const sesionesDia = fechaDiaISO
  ? todasSesiones.filter(s => String(s.s_fecha || '').substring(0,10) === fechaDiaISO)
  : todasSesiones;

const sesiones = sesionesDia.filter(s => 
  s.estado === 'ACTIVO' || s.estado === 'COMPLETADO'
);

let _liqLen; try { _liqLen = $('Leer Liquidaciones (informe)').all().length; } catch(e) { _liqLen = $('Leer Liquidaciones').all().length; }
  if (sesiones.length === 0 && !_liqLen) {
  return [{ json: { resumen: '⚠️ *Sin datos disponibles para hoy.*' } }];
}

// --- Fuente 2: Liquidaciones ---
let _liq; try { _liq = $('Leer Liquidaciones (informe)').all(); } catch(e) { _liq = $('Leer Liquidaciones').all(); }
const liquidaciones = _liq.map(i => i.json);

const mapLiq = {};
liquidaciones.forEach(l => {
  const guia  = (l['SER_IMPREG'] || '').toString().trim().toUpperCase();
  const total = Number(l['Suma de IMPCOB']) || 0;
  if (guia && total > 0) {
    mapLiq[guia] = {
      total,
      vehiculo: (l['VEHICULO'] || 'Sin nombre').toString().trim()
    };
  }
});

const guiasConSesion = new Set(sesiones.map(s => (s.guia || '').toString().trim().toUpperCase()));

const pendientes = Object.entries(mapLiq)
  .filter(([guia]) => !guiasConSesion.has(guia))
  .map(([guia, data]) => ({ guia, ...data }));

// --- Helpers ---
const fmt = v => Number(v).toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const limpiarGuia = (g) => {
  const match = g.toUpperCase().match(/([A-Z]+)-0*(\d+)/);
  return match ? `${match[1]}-${match[2]}` : g;
};

// --- Acumuladores ---
let totalEsperadoGlobal = 0;
let totalRecaudadoGlobal = 0;

// --- Procesar Secciones ---
const activas = sesiones.filter(s => s.estado === 'ACTIVO');
const completadas = sesiones.filter(s => s.estado === 'COMPLETADO');

function procesarSesion(s) {
  const guiaNorm = (s.guia || '').toString().trim().toUpperCase();
  const liq = (mapLiq[guiaNorm] && mapLiq[guiaNorm].total) || Number(s.liquidacion_total) || 0;
  const rec = Number(s.total_recaudado) || 0;

  totalEsperadoGlobal += liq;
  totalRecaudadoGlobal += rec;

  const pct = liq > 0 ? Math.round((rec / liq) * 100) : 0;
  return `- *${limpiarGuia(guiaNorm)}* (${s.transportista || 'S/N'})\n   └ ${fmt(rec)} / ${fmt(liq)} Bs (${pct}%)`;
}

// --- Construir Mensaje ---
const fecha = new Date().toLocaleDateString('es-BO', { day: '2-digit', month: '2-digit', year: 'numeric' });
let resumen = `📋 *Liquidaciones - ${fecha}*\n`;

// 1. PENDIENTES
if (pendientes.length > 0) {
  resumen += `\n⭕ *PENDIENTES (${pendientes.length})*\n`;
  resumen += pendientes.map(p => {
    totalEsperadoGlobal += p.total;
    return `- *${limpiarGuia(p.guia)}* (${p.vehiculo})\n   └ Esperado: ${fmt(p.total)} Bs`;
  }).join('\n');
}

// 2. EN CURSO
if (activas.length > 0) {
  resumen += `\n\n🟡 *EN CURSO (${activas.length})*\n`;
  resumen += activas.map(s => procesarSesion(s)).join('\n');
}

// 3. COMPLETADAS
if (completadas.length > 0) {
  resumen += `\n\n✅ *COMPLETADAS (${completadas.length})*\n`;
  resumen += completadas.map(s => procesarSesion(s)).join('\n');
}

// --- Resumen Final ---
const totalRestanteGlobal = totalEsperadoGlobal - totalRecaudadoGlobal;
const pctGlobal = totalEsperadoGlobal > 0 ? Math.round((totalRecaudadoGlobal / totalEsperadoGlobal) * 100) : 0;

resumen += `\n\n━━━━━━━━━━━━━━\n` +
           `📊 *TOTALES GENERALES*\n` +
           `• Esperado: ${fmt(totalEsperadoGlobal)} Bs\n` +
           `• Recaudado: ${fmt(totalRecaudadoGlobal)} Bs (*${pctGlobal}%*)\n` +
           `• Restante: ${fmt(totalRestanteGlobal)} Bs`;

if (sesiones.length > 0 && activas.length === 0 && pendientes.length === 0) {
  resumen += `\n\n🎉 *¡Todo completado!*`;
}

if ($('Buscar autorizado').first().json.tipo == "ADMIN"){
  resumen += `\n\n📂 Planilla: ${LINK_SHEET_LIQ}`;
}
// Solo mostramos el link a los admin


return [{ json: { resumen } }];

