// === Resolver Sucursal del transportista ===
// Lee el código de sucursal de la fila de 'autorizados' (columna 'sucursal')
// y lo convierte a sufijo de hoja usando la variable n8n:
//   SUCURSALES = COM:|LP:_LP|CBB:_CBB
// Mantiene intactos todos los campos que ya traía 'Buscar autorizado'.

const data = $input.item.json;

// 1) Construir el mapa desde la variable
const mapa = {};
String($vars.SUCURSALES || 'COM:').split('|').forEach(par => {
  const [pref, suf] = par.split(':');
  if (pref !== undefined && pref.trim() !== '') {
    mapa[pref.trim().toUpperCase()] = (suf || '').trim();
  }
});

// 2) Código de sucursal del transportista (fallback a COM = principal)
const codigo = String(data.sucursal || 'COM').trim().toUpperCase();

// 3) Sufijo de hoja resultante
const sufijo = (mapa[codigo] !== undefined) ? mapa[codigo] : '';

return [{
  json: {
    ...data,
    sucursal_codigo: codigo,
    sucursal_sufijo: sufijo
  }
}];

// === Sanitizar respuesta del admin (LLM) para mensaje interactivo WA ===
// WhatsApp interactive usa JSON; comillas o saltos crudos en el texto rompen el body.
// Este nodo limpia el texto sin depender de que el modelo obedezca.

const out = $input.item.json.output;
let texto = '';
try {
  texto = (Array.isArray(out) ? out[0].texto : out.texto) || '';
} catch (e) {
  texto = '';
}

// 1) Normalizar saltos de línea problemáticos a \n real controlado
texto = String(texto)
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n');

// 2) Quitar comillas dobles y simples tipográficas y rectas
texto = texto
  .replace(/[""]/g, '')   // comillas dobles tipográficas
  .replace(/['']/g, '')   // comillas simples tipográficas
  .replace(/"/g, '')       // comilla doble recta
  .replace(/'/g, '');      // comilla simple recta

// 3) WhatsApp body: limitar longitud (límite ~1024 en interactive body)
if (texto.length > 1000) texto = texto.slice(0, 997) + '...';

// 4) Texto de respaldo si quedó vacío
if (!texto.trim()) {
  texto = 'Hola, ¿en qué puedo ayudarte? Puedes pedirme el Informe Actual, el Reporte del Día o un Cierre de Guía.';
}

return [{
  json: {
    ...$input.item.json,
    texto_limpio: texto
  }
}];

